-- Degree Programs - Lot 8: internships, theses and defense preparation. Run after migration 016.
do $$ begin create type public.academic_internship_status as enum ('DRAFT','SUBMITTED','APPROVED','IN_PROGRESS','COMPLETED','UNDER_REVIEW','VALIDATED','REJECTED','CANCELLED'); exception when duplicate_object then null; end $$;
do $$ begin create type public.academic_supervision_progress as enum ('NOT_STARTED','ON_TRACK','AT_RISK','DELAYED','COMPLETED','BLOCKED'); exception when duplicate_object then null; end $$;
do $$ begin create type public.academic_thesis_status as enum ('PROPOSED','SUBMITTED','APPROVED','IN_PROGRESS','SUBMITTED_FOR_REVIEW','UNDER_REVIEW','READY_FOR_DEFENSE','DEFENDED','CORRECTIONS_REQUIRED','VALIDATED','REJECTED','ARCHIVED'); exception when duplicate_object then null; end $$;
do $$ begin create type public.academic_milestone_status as enum ('PLANNED','IN_PROGRESS','SUBMITTED','ACCEPTED','REVISION_REQUIRED','COMPLETED','CANCELLED'); exception when duplicate_object then null; end $$;
do $$ begin create type public.academic_defense_status as enum ('DRAFT','SCHEDULED','CONFIRMED','COMPLETED','POSTPONED','CANCELLED'); exception when duplicate_object then null; end $$;
do $$ begin create type public.academic_defense_decision as enum ('PENDING','PASSED','FAILED','CORRECTIONS_REQUIRED','ADJOURNED'); exception when duplicate_object then null; end $$;
do $$ begin create type public.academic_practicum_document_type as enum ('AGREEMENT','INSURANCE','MISSION_ORDER','TIMESHEET','SUPERVISION_REPORT','INTERNSHIP_REPORT','EVALUATION','THESIS_PROPOSAL','THESIS_DRAFT','THESIS_FINAL','PLAGIARISM_REPORT','DEFENSE_MINUTES','PRESENTATION','CORRECTION_PROOF','OTHER'); exception when duplicate_object then null; end $$;
create sequence if not exists public.academic_internship_code_seq;create sequence if not exists public.academic_thesis_code_seq;create sequence if not exists public.academic_milestone_code_seq;create sequence if not exists public.academic_defense_code_seq;

create table if not exists public.academic_internships(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,internship_number text not null unique,student_id uuid not null references public.academic_students(id) on delete restrict,program_id uuid not null references public.academic_programs(id) on delete restrict,academic_year_id uuid not null references public.academic_years(id) on delete restrict,semester_id uuid references public.academic_semesters(id) on delete restrict,course_id uuid references public.academic_courses(id) on delete restrict,
 organization_name text not null,organization_address text,organization_country text,department_or_unit text,position_title_fr text not null,position_title_en text not null,objectives_fr text not null,objectives_en text not null,workplace_supervisor_name text not null,workplace_supervisor_email citext,workplace_supervisor_phone text,academic_supervisor_id uuid references public.profiles(id) on delete set null,start_date date not null,end_date date not null,expected_hours numeric(8,2) not null check(expected_hours>0),completed_hours numeric(8,2) not null default 0 check(completed_hours>=0),status public.academic_internship_status not null default 'DRAFT',report_storage_path text,evaluation_score numeric(7,2) check(evaluation_score between 0 and 100),evaluation_comment text,submitted_by uuid references public.profiles(id),submitted_at timestamptz,validated_by uuid references public.profiles(id),validated_at timestamptz,rejection_reason text,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_date>=start_date),check(completed_hours<=expected_hours));
create table if not exists public.academic_internship_supervisions(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,internship_id uuid not null references public.academic_internships(id) on delete restrict,supervision_date date not null,supervisor_id uuid not null references public.profiles(id) on delete restrict,progress_status public.academic_supervision_progress not null,completed_hours numeric(8,2) check(completed_hours>=0),objectives_review_fr text not null,objectives_review_en text not null,comments_fr text not null,comments_en text not null,next_action_fr text,next_action_en text,next_action_due_date date,student_acknowledged_at timestamptz,created_at timestamptz not null default now(),unique(internship_id,supervision_date,supervisor_id));

create table if not exists public.academic_theses(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,thesis_number text not null unique,student_id uuid not null references public.academic_students(id) on delete restrict,program_id uuid not null references public.academic_programs(id) on delete restrict,academic_year_id uuid not null references public.academic_years(id) on delete restrict,title_fr text not null,title_en text not null,topic_fr text not null,topic_en text not null,research_question_fr text,research_question_en text,methodology_fr text,methodology_en text,supervisor_id uuid references public.profiles(id) on delete set null,co_supervisor_id uuid references public.profiles(id) on delete set null,proposal_date date,approval_date date,submission_date date,status public.academic_thesis_status not null default 'PROPOSED',document_storage_path text,plagiarism_status text check(plagiarism_status is null or plagiarism_status in('NOT_CHECKED','PENDING','CLEAR','REVIEW_REQUIRED','BLOCKED')),plagiarism_score numeric(5,2) check(plagiarism_score between 0 and 100),submitted_by uuid references public.profiles(id),submitted_at timestamptz,validated_by uuid references public.profiles(id),validated_at timestamptz,rejection_reason text,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(supervisor_id is null or supervisor_id<>co_supervisor_id));
create table if not exists public.academic_thesis_milestones(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,milestone_number text not null unique,thesis_id uuid not null references public.academic_theses(id) on delete restrict,title_fr text not null,title_en text not null,description_fr text not null,description_en text not null,due_date date not null,submitted_at timestamptz,reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,status public.academic_milestone_status not null default 'PLANNED',review_comment_fr text,review_comment_en text,storage_path text,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());

create table if not exists public.academic_defenses(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,defense_number text not null unique,thesis_id uuid not null references public.academic_theses(id) on delete restrict,student_id uuid not null references public.academic_students(id) on delete restrict,program_id uuid not null references public.academic_programs(id) on delete restrict,defense_date date not null,start_time time not null,end_time time,location_or_link text not null,jury_id uuid,presentation_score numeric(7,2) check(presentation_score between 0 and 100),document_score numeric(7,2) check(document_score between 0 and 100),final_score numeric(7,2) check(final_score between 0 and 100),decision public.academic_defense_decision not null default 'PENDING',comments_fr text,comments_en text,status public.academic_defense_status not null default 'DRAFT',scheduled_by uuid references public.profiles(id),completed_by uuid references public.profiles(id),completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(thesis_id),check(end_time is null or end_time>start_time));
create table if not exists public.academic_practicum_documents(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,student_id uuid not null references public.academic_students(id) on delete restrict,entity_type text not null check(entity_type in('INTERNSHIP','SUPERVISION','THESIS','MILESTONE','DEFENSE')),entity_id uuid not null,document_type public.academic_practicum_document_type not null,title_fr text not null,title_en text not null,storage_bucket text not null default 'academic-practicum-documents',storage_path text not null,original_file_name text not null,mime_type text,file_size_bytes bigint check(file_size_bytes is null or file_size_bytes>=0),version integer not null default 1 check(version>0),status public.academic_record_status not null default 'ACTIVE',uploaded_by uuid not null references public.profiles(id),uploaded_at timestamptz not null default now(),verified_by uuid references public.profiles(id),verified_at timestamptz,verification_comment text,unique(entity_type,entity_id,document_type,version));
create table if not exists public.academic_practicum_history(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,entity_type text not null check(entity_type in('INTERNSHIP','SUPERVISION','THESIS','MILESTONE','DEFENSE','DOCUMENT')),entity_id uuid not null,student_id uuid not null references public.academic_students(id) on delete restrict,old_status text,new_status text,action text not null,reason text not null,changed_by uuid references public.profiles(id),changed_at timestamptz not null default now());

create index if not exists academic_internships_student_idx on public.academic_internships(student_id,academic_year_id,status);
create index if not exists academic_internships_supervisor_idx on public.academic_internships(academic_supervisor_id,status);
create index if not exists academic_supervisions_internship_idx on public.academic_internship_supervisions(internship_id,supervision_date desc);
create index if not exists academic_theses_student_idx on public.academic_theses(student_id,program_id,status);
create index if not exists academic_theses_supervisor_idx on public.academic_theses(supervisor_id,status);
create index if not exists academic_milestones_thesis_idx on public.academic_thesis_milestones(thesis_id,due_date,status);
create index if not exists academic_defenses_program_idx on public.academic_defenses(program_id,defense_date,status);
create index if not exists academic_practicum_documents_entity_idx on public.academic_practicum_documents(entity_type,entity_id,version desc);
create index if not exists academic_practicum_history_entity_idx on public.academic_practicum_history(entity_type,entity_id,changed_at desc);

create or replace function public.academic_set_practicum_number() returns trigger language plpgsql as $$ begin
 if tg_table_name='academic_internships' and coalesce(new.internship_number,'')='' then new.internship_number:='INT-'||to_char(current_date,'YYYY')||'-'||lpad(nextval('public.academic_internship_code_seq')::text,5,'0');
 elsif tg_table_name='academic_theses' and coalesce(new.thesis_number,'')='' then new.thesis_number:='THS-'||to_char(current_date,'YYYY')||'-'||lpad(nextval('public.academic_thesis_code_seq')::text,5,'0');
 elsif tg_table_name='academic_thesis_milestones' and coalesce(new.milestone_number,'')='' then new.milestone_number:='MS-'||lpad(nextval('public.academic_milestone_code_seq')::text,6,'0');
 elsif tg_table_name='academic_defenses' and coalesce(new.defense_number,'')='' then new.defense_number:='DEF-'||to_char(current_date,'YYYY')||'-'||lpad(nextval('public.academic_defense_code_seq')::text,5,'0');end if;return new;end $$;
do $$ declare t text;begin foreach t in array array['academic_internships','academic_theses','academic_thesis_milestones','academic_defenses'] loop execute format('drop trigger if exists %I_number on public.%I',t,t);execute format('create trigger %I_number before insert on public.%I for each row execute function public.academic_set_practicum_number()',t,t);end loop;end $$;

create or replace function public.academic_transition_internship(p_id uuid,p_status public.academic_internship_status,p_reason text) returns public.academic_internships language plpgsql security definer set search_path=public as $$
declare r public.academic_internships;old public.academic_internship_status;allowed boolean;begin select * into r from public.academic_internships where id=p_id for update;if r.id is null then raise exception 'Internship not found';end if;old:=r.status;
allowed:=case when old='DRAFT' then p_status in('SUBMITTED','CANCELLED') when old='SUBMITTED' then p_status in('APPROVED','REJECTED') when old='REJECTED' then p_status='DRAFT' when old='APPROVED' then p_status='IN_PROGRESS' when old='IN_PROGRESS' then p_status in('COMPLETED','CANCELLED') when old='COMPLETED' then p_status='UNDER_REVIEW' when old='UNDER_REVIEW' then p_status in('VALIDATED','REJECTED') else false end;if not allowed then raise exception 'Invalid internship transition: % -> %',old,p_status;end if;
if not(exists(select 1 from public.academic_students s where s.id=r.student_id and s.user_id=auth.uid() and p_status in('SUBMITTED','CANCELLED','DRAFT'))or r.academic_supervisor_id=auth.uid()or public.academic_has_program_scope(r.organization_id,r.program_id,case when p_status in('APPROVED','VALIDATED','REJECTED') then 'internship.validate' else 'internship.manage' end))then raise exception 'Internship workflow permission required';end if;
if p_status='COMPLETED' and(r.completed_hours<r.expected_hours or r.report_storage_path is null)then raise exception 'Expected hours and internship report are required before completion';end if;
update public.academic_internships set status=p_status,submitted_by=case when p_status='SUBMITTED' then auth.uid() else submitted_by end,submitted_at=case when p_status='SUBMITTED' then now() else submitted_at end,validated_by=case when p_status='VALIDATED' then auth.uid() else validated_by end,validated_at=case when p_status='VALIDATED' then now() else validated_at end,rejection_reason=case when p_status='REJECTED' then p_reason else null end,updated_at=now() where id=p_id returning * into r;
insert into public.academic_practicum_history(organization_id,entity_type,entity_id,student_id,old_status,new_status,action,reason,changed_by)values(r.organization_id,'INTERNSHIP',r.id,r.student_id,old::text,p_status::text,'STATUS_CHANGED',coalesce(nullif(trim(p_reason),''),'Workflow transition'),auth.uid());return r;end $$;
create or replace function public.academic_transition_thesis(p_id uuid,p_status public.academic_thesis_status,p_reason text) returns public.academic_theses language plpgsql security definer set search_path=public as $$
declare r public.academic_theses;old public.academic_thesis_status;allowed boolean;begin select * into r from public.academic_theses where id=p_id for update;if r.id is null then raise exception 'Thesis not found';end if;old:=r.status;
allowed:=case when old='PROPOSED' then p_status='SUBMITTED' when old='SUBMITTED' then p_status in('APPROVED','REJECTED') when old='REJECTED' then p_status='PROPOSED' when old='APPROVED' then p_status='IN_PROGRESS' when old='IN_PROGRESS' then p_status='SUBMITTED_FOR_REVIEW' when old='SUBMITTED_FOR_REVIEW' then p_status in('UNDER_REVIEW','CORRECTIONS_REQUIRED') when old='UNDER_REVIEW' then p_status in('READY_FOR_DEFENSE','CORRECTIONS_REQUIRED') when old='CORRECTIONS_REQUIRED' then p_status='SUBMITTED_FOR_REVIEW' when old='READY_FOR_DEFENSE' then p_status='DEFENDED' when old='DEFENDED' then p_status in('VALIDATED','CORRECTIONS_REQUIRED') else false end;if not allowed then raise exception 'Invalid thesis transition: % -> %',old,p_status;end if;
if not(exists(select 1 from public.academic_students s where s.id=r.student_id and s.user_id=auth.uid() and p_status in('SUBMITTED','SUBMITTED_FOR_REVIEW'))or r.supervisor_id=auth.uid()or r.co_supervisor_id=auth.uid()or public.academic_has_program_scope(r.organization_id,r.program_id,case when p_status in('APPROVED','READY_FOR_DEFENSE','VALIDATED','REJECTED') then 'thesis.validate' else 'thesis.manage' end))then raise exception 'Thesis workflow permission required';end if;
if p_status='READY_FOR_DEFENSE' and(r.document_storage_path is null or r.plagiarism_status<>'CLEAR')then raise exception 'Final document and clear plagiarism check are required';end if;
update public.academic_theses set status=p_status,approval_date=case when p_status='APPROVED' then current_date else approval_date end,submission_date=case when p_status='SUBMITTED_FOR_REVIEW' then current_date else submission_date end,submitted_by=case when p_status in('SUBMITTED','SUBMITTED_FOR_REVIEW') then auth.uid() else submitted_by end,submitted_at=case when p_status in('SUBMITTED','SUBMITTED_FOR_REVIEW') then now() else submitted_at end,validated_by=case when p_status='VALIDATED' then auth.uid() else validated_by end,validated_at=case when p_status='VALIDATED' then now() else validated_at end,rejection_reason=case when p_status='REJECTED' then p_reason else null end,updated_at=now() where id=p_id returning * into r;
insert into public.academic_practicum_history(organization_id,entity_type,entity_id,student_id,old_status,new_status,action,reason,changed_by)values(r.organization_id,'THESIS',r.id,r.student_id,old::text,p_status::text,'STATUS_CHANGED',coalesce(nullif(trim(p_reason),''),'Workflow transition'),auth.uid());return r;end $$;

