do $$ declare t text;begin foreach t in array array['academic_internships','academic_internship_supervisions','academic_theses','academic_thesis_milestones','academic_defenses','academic_practicum_documents','academic_practicum_history']loop execute format('alter table public.%I enable row level security',t);end loop;end $$;
create or replace function public.academic_can_read_practicum(p_student_id uuid,p_program_id uuid,p_supervisor_id uuid,p_permission text)returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.academic_students s where s.id=p_student_id and s.user_id=auth.uid())or p_supervisor_id=auth.uid()or public.academic_has_program_scope((select organization_id from public.academic_students where id=p_student_id),p_program_id,p_permission)$$;
grant execute on function public.academic_can_read_practicum(uuid,uuid,uuid,text)to authenticated;
drop policy if exists "internships read" on public.academic_internships;create policy "internships read" on public.academic_internships for select to authenticated using(public.academic_can_read_practicum(student_id,program_id,academic_supervisor_id,'internship.read'));
drop policy if exists "internships create" on public.academic_internships;create policy "internships create" on public.academic_internships for insert to authenticated with check(created_by=auth.uid()and(exists(select 1 from public.academic_students s where s.id=student_id and s.user_id=auth.uid())or public.academic_has_program_scope(organization_id,program_id,'internship.manage')));
drop policy if exists "supervisions read" on public.academic_internship_supervisions;create policy "supervisions read" on public.academic_internship_supervisions for select to authenticated using(exists(select 1 from public.academic_internships i where i.id=internship_id and public.academic_can_read_practicum(i.student_id,i.program_id,i.academic_supervisor_id,'internship.read')));
drop policy if exists "supervisions create" on public.academic_internship_supervisions;create policy "supervisions create" on public.academic_internship_supervisions for insert to authenticated with check(supervisor_id=auth.uid()and exists(select 1 from public.academic_internships i where i.id=internship_id and(i.academic_supervisor_id=auth.uid()or public.academic_has_program_scope(i.organization_id,i.program_id,'internship.manage'))));
drop policy if exists "theses read" on public.academic_theses;create policy "theses read" on public.academic_theses for select to authenticated using(public.academic_can_read_practicum(student_id,program_id,supervisor_id,'thesis.read')or co_supervisor_id=auth.uid());
drop policy if exists "theses create" on public.academic_theses;create policy "theses create" on public.academic_theses for insert to authenticated with check(created_by=auth.uid()and(exists(select 1 from public.academic_students s where s.id=student_id and s.user_id=auth.uid())or public.academic_has_program_scope(organization_id,program_id,'thesis.manage')));
drop policy if exists "milestones read" on public.academic_thesis_milestones;create policy "milestones read" on public.academic_thesis_milestones for select to authenticated using(exists(select 1 from public.academic_theses t where t.id=thesis_id and(public.academic_can_read_practicum(t.student_id,t.program_id,t.supervisor_id,'thesis.read')or t.co_supervisor_id=auth.uid())));
drop policy if exists "milestones create" on public.academic_thesis_milestones;create policy "milestones create" on public.academic_thesis_milestones for insert to authenticated with check(created_by=auth.uid()and exists(select 1 from public.academic_theses t where t.id=thesis_id and(public.academic_can_read_practicum(t.student_id,t.program_id,t.supervisor_id,'thesis.manage')or t.co_supervisor_id=auth.uid())));
drop policy if exists "defenses read" on public.academic_defenses;create policy "defenses read" on public.academic_defenses for select to authenticated using(public.academic_can_read_practicum(student_id,program_id,null,'thesis.read'));
drop policy if exists "practicum documents read" on public.academic_practicum_documents;create policy "practicum documents read" on public.academic_practicum_documents for select to authenticated using(exists(select 1 from public.academic_students s where s.id=student_id and(s.user_id=auth.uid()or public.academic_has_program_scope(organization_id,s.current_program_id,'internship.read')or public.academic_has_program_scope(organization_id,s.current_program_id,'thesis.read'))));
drop policy if exists "practicum documents create" on public.academic_practicum_documents;create policy "practicum documents create" on public.academic_practicum_documents for insert to authenticated with check(uploaded_by=auth.uid()and exists(select 1 from public.academic_students s where s.id=student_id and(s.user_id=auth.uid()or public.academic_has_program_scope(organization_id,s.current_program_id,'internship.manage')or public.academic_has_program_scope(organization_id,s.current_program_id,'thesis.manage'))));
drop policy if exists "practicum history read" on public.academic_practicum_history;create policy "practicum history read" on public.academic_practicum_history for select to authenticated using(exists(select 1 from public.academic_students s where s.id=student_id and(s.user_id=auth.uid()or public.academic_has_program_scope(organization_id,s.current_program_id,'internship.read')or public.academic_has_program_scope(organization_id,s.current_program_id,'thesis.read'))));

revoke all on function public.academic_transition_internship(uuid,public.academic_internship_status,text)from public;revoke all on function public.academic_transition_thesis(uuid,public.academic_thesis_status,text)from public;
grant execute on function public.academic_transition_internship(uuid,public.academic_internship_status,text)to authenticated;grant execute on function public.academic_transition_thesis(uuid,public.academic_thesis_status,text)to authenticated;
insert into storage.buckets(id,name,public)values('academic-practicum-documents','academic-practicum-documents',false)on conflict(id)do nothing;
drop policy if exists "academic practicum files read" on storage.objects;create policy "academic practicum files read" on storage.objects for select to authenticated using(bucket_id='academic-practicum-documents'and(storage.foldername(name))[1]~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'and exists(select 1 from public.academic_students s where s.id=(storage.foldername(name))[1]::uuid and(s.user_id=auth.uid()or public.academic_has_program_scope(s.organization_id,s.current_program_id,'internship.read')or public.academic_has_program_scope(s.organization_id,s.current_program_id,'thesis.read'))));
drop policy if exists "academic practicum files upload" on storage.objects;create policy "academic practicum files upload" on storage.objects for insert to authenticated with check(bucket_id='academic-practicum-documents'and(storage.foldername(name))[1]~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'and exists(select 1 from public.academic_students s where s.id=(storage.foldername(name))[1]::uuid and(s.user_id=auth.uid()or public.academic_has_program_scope(s.organization_id,s.current_program_id,'internship.manage')or public.academic_has_program_scope(s.organization_id,s.current_program_id,'thesis.manage'))));insert into public.academic_role_permissions(role,permission_code,description_fr,description_en)values
('INTERNSHIP_SUPERVISOR','practicum.read','Acceder a l espace stages et memoires','Access internships and theses area'),('THESIS_SUPERVISOR','practicum.read','Acceder a l espace stages et memoires','Access internships and theses area'),('PROGRAM_COORDINATOR','practicum.read','Acceder a l espace stages et memoires','Access internships and theses area'),('ACADEMIC_SECRETARY','practicum.read','Acceder a l espace stages et memoires','Access internships and theses area'),('ACADEMIC_ADMIN','practicum.read','Acceder a l espace stages et memoires','Access internships and theses area'),('SUPER_ADMIN','practicum.read','Acceder a l espace stages et memoires','Access internships and theses area')
on conflict(role,permission_code)do update set description_fr=excluded.description_fr,description_en=excluded.description_en;
create or replace function public.academic_register_practicum_document(p_student_id uuid,p_entity_type text,p_entity_id uuid,p_document_type public.academic_practicum_document_type,p_title_fr text,p_title_en text,p_storage_path text,p_original_file_name text,p_mime_type text,p_file_size_bytes bigint)
returns public.academic_practicum_documents language plpgsql security definer set search_path=public as $$
declare s public.academic_students;allowed boolean:=false;v integer;r public.academic_practicum_documents;begin
 select * into s from public.academic_students where id=p_student_id;if s.id is null then raise exception 'Student not found';end if;
 allowed:=s.user_id=auth.uid()or public.academic_has_program_scope(s.organization_id,s.current_program_id,case when p_entity_type in('INTERNSHIP','SUPERVISION')then 'internship.manage' else 'thesis.manage' end);if not allowed then raise exception 'Document upload permission required';end if;
 if p_storage_path not like p_student_id::text||'/%' then raise exception 'Storage path must begin with the student ID';end if;
 if p_entity_type='INTERNSHIP' then allowed:=exists(select 1 from public.academic_internships where id=p_entity_id and student_id=p_student_id);
 elsif p_entity_type='SUPERVISION' then allowed:=exists(select 1 from public.academic_internship_supervisions x join public.academic_internships i on i.id=x.internship_id where x.id=p_entity_id and i.student_id=p_student_id);
 elsif p_entity_type='THESIS' then allowed:=exists(select 1 from public.academic_theses where id=p_entity_id and student_id=p_student_id);
 elsif p_entity_type='MILESTONE' then allowed:=exists(select 1 from public.academic_thesis_milestones x join public.academic_theses t on t.id=x.thesis_id where x.id=p_entity_id and t.student_id=p_student_id);
 elsif p_entity_type='DEFENSE' then allowed:=exists(select 1 from public.academic_defenses where id=p_entity_id and student_id=p_student_id);else allowed:=false;end if;if not allowed then raise exception 'Document entity does not belong to student';end if;
 select coalesce(max(version),0)+1 into v from public.academic_practicum_documents where entity_type=p_entity_type and entity_id=p_entity_id and document_type=p_document_type;
 insert into public.academic_practicum_documents(organization_id,student_id,entity_type,entity_id,document_type,title_fr,title_en,storage_path,original_file_name,mime_type,file_size_bytes,version,uploaded_by)values(s.organization_id,p_student_id,p_entity_type,p_entity_id,p_document_type,p_title_fr,p_title_en,p_storage_path,p_original_file_name,p_mime_type,p_file_size_bytes,v,auth.uid())returning * into r;
 if p_entity_type='INTERNSHIP' and p_document_type='INTERNSHIP_REPORT' then update public.academic_internships set report_storage_path=p_storage_path,updated_at=now()where id=p_entity_id;
 elsif p_entity_type='THESIS' and p_document_type='THESIS_FINAL' then update public.academic_theses set document_storage_path=p_storage_path,updated_at=now()where id=p_entity_id;elsif p_entity_type='MILESTONE' then update public.academic_thesis_milestones set storage_path=p_storage_path,updated_at=now()where id=p_entity_id;end if;
 insert into public.academic_practicum_history(organization_id,entity_type,entity_id,student_id,action,reason,changed_by)values(s.organization_id,'DOCUMENT',r.id,p_student_id,'DOCUMENT_VERSION_ADDED','Version '||v||' - '||p_document_type::text,auth.uid());return r;end $$;

create or replace function public.academic_update_internship_progress(p_id uuid,p_completed_hours numeric,p_evaluation_score numeric,p_evaluation_comment text,p_reason text)returns public.academic_internships language plpgsql security definer set search_path=public as $$
declare r public.academic_internships;begin select * into r from public.academic_internships where id=p_id for update;if r.id is null then raise exception 'Internship not found';end if;if not(r.academic_supervisor_id=auth.uid()or public.academic_has_program_scope(r.organization_id,r.program_id,'internship.manage'))then raise exception 'Internship management permission required';end if;if p_completed_hours<0 or p_completed_hours>r.expected_hours then raise exception 'Completed hours must be between zero and expected hours';end if;
 update public.academic_internships set completed_hours=p_completed_hours,evaluation_score=p_evaluation_score,evaluation_comment=p_evaluation_comment,updated_at=now()where id=p_id returning * into r;insert into public.academic_practicum_history(organization_id,entity_type,entity_id,student_id,action,reason,changed_by)values(r.organization_id,'INTERNSHIP',r.id,r.student_id,'PROGRESS_UPDATED',p_reason,auth.uid());return r;end $$;

create or replace function public.academic_update_thesis_review(p_id uuid,p_plagiarism_status text,p_plagiarism_score numeric,p_reason text)returns public.academic_theses language plpgsql security definer set search_path=public as $$
declare r public.academic_theses;begin select * into r from public.academic_theses where id=p_id for update;if r.id is null then raise exception 'Thesis not found';end if;if not(r.supervisor_id=auth.uid()or r.co_supervisor_id=auth.uid()or public.academic_has_program_scope(r.organization_id,r.program_id,'thesis.manage'))then raise exception 'Thesis management permission required';end if;if p_plagiarism_status not in('NOT_CHECKED','PENDING','CLEAR','REVIEW_REQUIRED','BLOCKED')or p_plagiarism_score<0 or p_plagiarism_score>100 then raise exception 'Invalid plagiarism review';end if;
 update public.academic_theses set plagiarism_status=p_plagiarism_status,plagiarism_score=p_plagiarism_score,updated_at=now()where id=p_id returning * into r;insert into public.academic_practicum_history(organization_id,entity_type,entity_id,student_id,action,reason,changed_by)values(r.organization_id,'THESIS',r.id,r.student_id,'PLAGIARISM_REVIEWED',p_reason,auth.uid());return r;end $$;
revoke all on function public.academic_register_practicum_document(uuid,text,uuid,public.academic_practicum_document_type,text,text,text,text,text,bigint)from public;
revoke all on function public.academic_update_internship_progress(uuid,numeric,numeric,text,text)from public;
revoke all on function public.academic_update_thesis_review(uuid,text,numeric,text)from public;
grant execute on function public.academic_register_practicum_document(uuid,text,uuid,public.academic_practicum_document_type,text,text,text,text,text,bigint)to authenticated;
grant execute on function public.academic_update_internship_progress(uuid,numeric,numeric,text,text)to authenticated;
grant execute on function public.academic_update_thesis_review(uuid,text,numeric,text)to authenticated;
create or replace function public.academic_transition_thesis_milestone(p_id uuid,p_status public.academic_milestone_status,p_storage_path text,p_comment_fr text,p_comment_en text,p_reason text)returns public.academic_thesis_milestones language plpgsql security definer set search_path=public as $$
declare r public.academic_thesis_milestones;t public.academic_theses;old public.academic_milestone_status;allowed boolean;begin select * into r from public.academic_thesis_milestones where id=p_id for update;select * into t from public.academic_theses where id=r.thesis_id;if r.id is null then raise exception 'Milestone not found';end if;old:=r.status;allowed:=case when old='PLANNED' then p_status='IN_PROGRESS' when old='IN_PROGRESS' then p_status='SUBMITTED' when old='SUBMITTED' then p_status in('ACCEPTED','REVISION_REQUIRED') when old='REVISION_REQUIRED' then p_status='SUBMITTED' when old='ACCEPTED' then p_status='COMPLETED' else false end;if not allowed then raise exception 'Invalid milestone transition: % -> %',old,p_status;end if;
if p_status='SUBMITTED' then if not exists(select 1 from public.academic_students s where s.id=t.student_id and s.user_id=auth.uid())and not(t.supervisor_id=auth.uid()or t.co_supervisor_id=auth.uid())then raise exception 'Student or supervisor permission required';end if;if coalesce(p_storage_path,r.storage_path) is null then raise exception 'A milestone file is required';end if;elsif not(t.supervisor_id=auth.uid()or t.co_supervisor_id=auth.uid()or public.academic_has_program_scope(t.organization_id,t.program_id,'thesis.manage'))then raise exception 'Milestone review permission required';end if;
update public.academic_thesis_milestones set status=p_status,storage_path=coalesce(p_storage_path,storage_path),submitted_at=case when p_status='SUBMITTED' then now()else submitted_at end,reviewed_by=case when p_status in('ACCEPTED','REVISION_REQUIRED','COMPLETED')then auth.uid()else reviewed_by end,reviewed_at=case when p_status in('ACCEPTED','REVISION_REQUIRED','COMPLETED')then now()else reviewed_at end,review_comment_fr=coalesce(p_comment_fr,review_comment_fr),review_comment_en=coalesce(p_comment_en,review_comment_en),updated_at=now()where id=p_id returning * into r;
insert into public.academic_practicum_history(organization_id,entity_type,entity_id,student_id,old_status,new_status,action,reason,changed_by)values(r.organization_id,'MILESTONE',r.id,t.student_id,old::text,p_status::text,'STATUS_CHANGED',p_reason,auth.uid());return r;end $$;

create or replace function public.academic_schedule_defense(p_thesis_id uuid,p_date date,p_start_time time,p_end_time time,p_location_or_link text,p_reason text)returns public.academic_defenses language plpgsql security definer set search_path=public as $$
declare t public.academic_theses;r public.academic_defenses;begin select * into t from public.academic_theses where id=p_thesis_id for update;if t.id is null then raise exception 'Thesis not found';end if;if t.status<>'READY_FOR_DEFENSE' then raise exception 'Thesis must be ready for defense';end if;if not public.academic_has_program_scope(t.organization_id,t.program_id,'thesis.validate')then raise exception 'Defense scheduling permission required';end if;if p_date<current_date or(p_end_time is not null and p_end_time<=p_start_time)then raise exception 'Invalid defense schedule';end if;
insert into public.academic_defenses(organization_id,thesis_id,student_id,program_id,defense_date,start_time,end_time,location_or_link,status,scheduled_by)values(t.organization_id,t.id,t.student_id,t.program_id,p_date,p_start_time,p_end_time,p_location_or_link,'SCHEDULED',auth.uid())returning * into r;insert into public.academic_practicum_history(organization_id,entity_type,entity_id,student_id,new_status,action,reason,changed_by)values(t.organization_id,'DEFENSE',r.id,t.student_id,'SCHEDULED','DEFENSE_SCHEDULED',p_reason,auth.uid());return r;end $$;
revoke all on function public.academic_transition_thesis_milestone(uuid,public.academic_milestone_status,text,text,text,text)from public;
revoke all on function public.academic_schedule_defense(uuid,date,time,time,text,text)from public;
grant execute on function public.academic_transition_thesis_milestone(uuid,public.academic_milestone_status,text,text,text,text)to authenticated;
grant execute on function public.academic_schedule_defense(uuid,date,time,time,text,text)to authenticated;